#ifndef __BLKCACHE_H__
#define __BLKCACHE_H__

#include "TYPES.H"
#include "iomgr.h"

 /* ==================================================================
  *  Pointer-width types (32-bit now, ready for 64-bit)
  * ================================================================== */

#if defined(_M_AMD64) || defined(_M_X64) || defined(__x86_64__)
typedef unsigned long long  __SECTOR_T;
#define SECTOR_T_FMT        "%016llX"
#define SECTOR_T_MAX        0xFFFFFFFFFFFFFFFFULL
#else
typedef unsigned long       __SECTOR_T;
#define SECTOR_T_FMT        "%08X"
#define SECTOR_T_MAX        0xFFFFFFFFUL
#endif

/* ==================================================================
 *  Buffer flags
 * ================================================================== */

#define BLK_BUF_VALID        0x01U    /* Buffer holds valid sector data       */
#define BLK_BUF_DIRTY        0x02U    /* Data modified, needs write-back      */
#define BLK_BUF_IO_BUSY      0x04U    /* Disk I/O in progress (read or write) */
#define BLK_BUF_FLUSHING     0x08U    /* Being written by background thread   */

#define BLK_BUF_BUSY_MASK    (BLK_BUF_IO_BUSY | BLK_BUF_FLUSHING)

 /* ==================================================================
  *  Sizing constants
  * ================================================================== */

#define BLK_CACHE_HASH_BITS      8
#define BLK_CACHE_HASH_SIZE      (1U << BLK_CACHE_HASH_BITS)   /* 256 buckets */
#define BLK_CACHE_HASH_MASK      (BLK_CACHE_HASH_SIZE - 1U)

#define BLK_CACHE_DEFAULT_MAX    1024       /* buffers per cache instance       */
#define BLK_CACHE_READAHEAD      8          /* sectors to prefetch sequentially */
#define BLK_CACHE_FLUSH_INTERVAL 800        /* background flush period (ms)     */
#define BLK_CACHE_IO_TIMEOUT     3200       /* time out value of I/O operation  */

  /* ==================================================================
   *  Buffer head  (metadata)  +  inline data
   *
   *  Memory layout:  [ __BLK_BUF_HEAD | padding | sector_data[sector_size] ]
   *  Allocated as one contiguous KMemAlloc block.
   * ================================================================== */

typedef struct tag__BLK_BUF_HEAD {
	/* ---- hash chain ---- */
	struct tag__BLK_BUF_HEAD*    pHashNext;

	/* ---- LRU doubly-linked list ---- */
	struct tag__BLK_BUF_HEAD*    pLruPrev;
	struct tag__BLK_BUF_HEAD*    pLruNext;

	/* ---- dirty doubly-linked list (valid only when DIRTY is set) ---- */
	struct tag__BLK_BUF_HEAD*    pDirtyPrev;
	struct tag__BLK_BUF_HEAD*    pDirtyNext;

	/* ---- temporary single-linked list (flush / invalidate batches) ---- */
	struct tag__BLK_BUF_HEAD*    pBatchNext;

	/* ---- identity ---- */
	__SECTOR_T      SectorNum;          /* starting sector number             */
	DWORD           dwFlags;            /* VALID | DIRTY | IO_BUSY | FLUSHING */
	DWORD           dwRefCount;         /* pin count -- eviction blocked if >0 */

	/* ---- back-pointer ---- */
	struct tag__BLK_CACHE*  pOwner;

	/* ---- data pointer (points to memory immediately after the head) ---- */
	BYTE*           pData;

	/* ---- transient (written by I/O phase, read by cleanup phase) ---- */
	BOOL            bIoResult;          /* TRUE if last disk op succeeded     */
} __BLK_BUF_HEAD;

/* Size of head rounded up to 8-byte alignment. */
#define BLK_BUF_HEAD_SIZE  \
    ((sizeof(__BLK_BUF_HEAD) + 7U) & ~7U)

/* Total allocation for one buffer (head + sector payload). */
#define BLK_BUF_TOTAL_SIZE(sector_size)  \
    (BLK_BUF_HEAD_SIZE + (sector_size))

/* ==================================================================
 *  Cache instance  (one per partition / block device)
 * ================================================================== */

typedef struct tag__BLK_CACHE {
	/* 
	 * The device is the cache object associated partition
	 * object, and cache object is a member of partition
	 * extension, so the cache object could be located by
	 * accessing pDevice->lpDevExtension->pBlockCache.
	 */
	__DEVICE_OBJECT*        pDevice;

	/* bytes per sector, from pDevice */
	DWORD                   dwBlockSize;        

	/* ---- buffer pool ---- */
	__BLK_BUF_HEAD*         pBufPool;           /* contiguous array of heads+data   */
	DWORD                   dwMaxBuffers;       /* capacity                         */
	DWORD                   dwAllocated;        /* currently in pool                */
	DWORD                   dwReadAheadNum;     /* How many blocks read ahead.      */

	/* ---- hash table ---- */
	__BLK_BUF_HEAD*         pHashBuckets[BLK_CACHE_HASH_SIZE];

	/* ---- LRU sentinel (circular doubly-linked) ---- */
	__BLK_BUF_HEAD          LruSentinel;

	/* ---- dirty sentinel (circular doubly-linked) ---- */
	__BLK_BUF_HEAD          DirtySentinel;

	/* ---- background flush thread ---- */
	__KERNEL_THREAD_OBJECT* hFlushThread;
	volatile BOOL           bFlushThreadStop;   /* signal to exit                   */
	volatile BOOL           bFlushThreadExited; /* thread has returned              */
	DWORD                   dwFlushIntervalMs;  /* sleep interval (default 500 ms)  */

	/* ---- statistics ---- */
	DWORD                   dwHitCount;
	DWORD                   dwMissCount;
	DWORD                   dwReadAheadCount;
	DWORD                   dwBackgroundFlushCount;
	DWORD                   dwWriteBackCount;
	DWORD                   dwBackThreadWake;

	/* ---- synchronization ---- */
	__SPIN_LOCK             SpinLock;

	/*
	 * Mutex object to protect the block cache object.
	 * We use one BIG LOCK to protect the WHOLE cache
	 * object, and we will optimize this later.
	 */
	__MUTEX*                mutex;

	/* ---- sequential-access detector ---- */
	__SECTOR_T              LastReadEndSector;
} __BLK_CACHE;

/* ==================================================================
 *  Public API
 * ================================================================== */

__BLK_CACHE* BlkCacheCreate(__DEVICE_OBJECT* pDevice, DWORD dwMaxBufs,
	DWORD dwReadAheadNum);

VOID BlkCacheDestroy(__BLK_CACHE* pCache);

DWORD BlkCacheRead(
	__BLK_CACHE*    pCache,
	__SECTOR_T      dwStartSector,
	DWORD           dwSectorNum,
	BYTE*           pBuffer);

DWORD BlkCacheWrite(
	__BLK_CACHE*    pCache,
	__SECTOR_T      dwStartSector,
	DWORD           dwSectorNum,
	const BYTE*     pBuffer);

BOOL BlkCacheFlushRange(
	__BLK_CACHE*    pCache,
	__SECTOR_T      dwStartSector,
	DWORD           dwSectorNum);

VOID BlkCacheInvalidateRange(
	__BLK_CACHE*    pCache,
	__SECTOR_T      dwStartSector,
	DWORD           dwSectorNum);

VOID BlkCacheGetStats(
	__BLK_CACHE*    pCache,
	DWORD*          pHitCount,
	DWORD*          pMissCount,
	DWORD*          pDirtyCount,
	DWORD*          pBackThreadWake,
	DWORD*          pReadAhead,
	DWORD*          pWriteBack);

#endif /* __BLKCACHE_H__ */
